<script>
(()=>{const form=document.getElementById('checkout-form'),steps=document.querySelectorAll('[data-checkout-step]'),labels=document.querySelectorAll('[data-step-label]'),mobileActions=document.querySelectorAll('[data-mobile-action]');function showStep(name){steps.forEach(step=>step.classList.toggle('hidden',step.dataset.checkoutStep!==name));labels.forEach(label=>{const active=label.dataset.stepLabel===name;label.classList.toggle('bg-emerald-800',active);label.classList.toggle('text-white',active);label.classList.toggle('text-slate-400',!active)});mobileActions.forEach(action=>{const active=action.dataset.mobileAction===name;action.classList.toggle('hidden',!active);action.classList.toggle('flex',active)});window.scrollTo({top:0,behavior:'smooth'})}function continueToPayment(){const fields=[...form.querySelectorAll('[data-checkout-step="details"] input,[data-checkout-step="details"] textarea')];const invalid=fields.find(field=>!field.checkValidity());if(invalid){invalid.reportValidity();invalid.focus();return}showStep('payment')}document.getElementById('continue-payment').addEventListener('click',continueToPayment);document.getElementById('continue-payment-mobile').addEventListener('click',continueToPayment);document.querySelectorAll('#back-details,[data-back-details]').forEach(button=>button.addEventListener('click',()=>showStep('details')));const proofInput=document.getElementById('proof-input'),proofAction=document.getElementById('proof-action'),proofTexts=document.querySelectorAll('[data-proof-action-text]');proofInput.addEventListener('change',()=>{if(!proofInput.files.length)return;proofAction.classList.add('pointer-events-none','opacity-70');proofTexts.forEach(text=>text.textContent='Mengirim pesanan…');form.requestSubmit()});@if($errors->has('proof')) showStep('payment'); @endif})();
</script>
